from pathlib import Path
import re,html,markdown
from playwright.sync_api import sync_playwright
import fitz
out=Path(__file__).resolve().parents[1]/'guide'
src=(Path(__file__).resolve().parent/'GUIDE-TWO-SITES-V2.md').read_text()
parts=re.split(r'^## \d+\. ',src,flags=re.M)
def md(s): return markdown.markdown(s,extensions=['tables','fenced_code'])
pages=[]
def add(kicker,title,body,cls=''):
 pages.append(f'<section class="page {cls}"><div class="kicker">@NIKOLSKAYA.AI <span>{kicker}</span></div><h1>{title}</h1>{body}</section>')
def img(file,cls='shot'):return f'<img class="{cls}" src="{file}">'
add('УРОК 01 / ОБНОВЛЁННЫЙ ГАЙД','Ваш первый<br>сайт с ИИ.', '<p class="lead">Урок 1. От пустой папки<br>до своего готового сайта.</p>'+img('nikolskaya-1440.png')+ '<div class="pill">САЙТ-ВИЗИТКА</div> <div class="pill">САЙТ ПРОЕКТА</div><p class="cover-bottom">Свои тексты. Свои фотографии. Готовые промпты.<br>Без опыта программирования.</p>','cover')
add('НАЧНИТЕ ЗДЕСЬ','Два примера.<br>Ваше содержание.', '<div class="example">'+img('nikolskaya-1440.png')+'<h3>01 / Личный сайт</h3><p>Имя слева, ваш аватар справа, логотипы в одну линию и чёрный фон.</p></div><div class="example">'+img('opora-1440.png')+'<h3>02 / Сайт проекта</h3><p>Редакционная типографика, фотоколлаж и навигация по главам. Учебный пример — вымышленная школа «Опора».</p></div><div class="note">В промптах замените всё в квадратных скобках своими данными. Сайты-примеры нужны как визуальный ориентир.</div>')
add('МАРШРУТ','Как устроена работа', '<div class="steps">'+''.join(f'<div><b>0{i}</b><h3>{t}</h3><p>{d}</p></div>' for i,(t,d) in enumerate([('Соберите материалы','Имя или название компании, тексты, фото и контакты.'),('Откройте Codex','Выберите папку, где появятся файлы вашего сайта.'),('Добавьте навыки','Установите инструкции для структуры и дизайна.'),('Отправьте промпт','Выберите визитку или компанию и заполните свои данные.'),('Проверьте и сохраните','Публикация на GitHub и деплой — на втором уроке.')],1))+'</div><div class="note">Промпты в PDF можно выделять и копировать. Если копирование добавило лишние переносы, используйте приложенный текстовый файл.</div>')
for idx in [1,2]:
 title,body=parts[idx].split('\n',1)
 add(f'ШАГ 0{idx}',title,md(body))
title,body=parts[3].split('\n',1)
a,terminal=body.split('### Установка через терминал')
intro,install=a.split('### Установка без терминала')
add('ШАГ 03 / НАВЫКИ','Что такое скиллы',md(intro)+'<div class="note">Выберите один способ установки на следующих страницах. Устанавливать один и тот же навык всеми способами не нужно.</div>')
add('ШАГ 03 / ПРОСТОЙ СПОСОБ','Попросите Codex<br>установить навыки',md(install))
add('ШАГ 03 / АЛЬТЕРНАТИВА','Установка вручную',md('### Через терминал\n'+terminal)+md('### Как скачать ZIP с GitHub\n1. Откройте репозиторий автора по ссылке из таблицы навыков. Перейдите на главную страницу репозитория.\n2. Нажмите **Code → Download ZIP** и распакуйте архив.\n3. Внутри найдите `skills/landing-page-design`, `skills/taste-skill` или `skills/hallmark` — по выбранному репозиторию. В папке должен быть `SKILL.md`. Сам ZIP ещё не означает установку.\n4. Передайте Codex путь к распакованной папке и отправьте запрос ниже.\n\n```text\nУстанови навык из локальной папки [ПОЛНЫЙ ПУТЬ]. Проверь SKILL.md и сохрани все необходимые файлы навыка. Сообщи, куда установлен навык и как проверить его доступность.\n```'))
for idx,site,label in [(4,'nikolskaya-romans','Сайт-визитка'),(5,'opora','Сайт проекта')]:
 title,body=parts[idx].split('\n',1)
 before,prompt,after=body.split('```text',1)[0],body.split('```text',1)[1].split('```',1)[0],body.split('```text',1)[1].split('```',1)[1]
 url=f'https://ekaterinaglowme.github.io/ai-sites-showcase/{site}/'
 add(f'ШАГ 0{idx} / ВИЗУАЛЬНЫЙ ОРИЕНТИР',label,img('nikolskaya-1440.png' if idx==4 else 'opora-1440.png')+md(before)+f'<p><a href="{url}">Открыть сайт-пример ↗</a></p><div class="note">Далее — полный промпт на двух страницах. Скопируйте обе части в одно сообщение, заполните поля и приложите фотографии.</div>')
 blocks=prompt.strip().split('\n\n')
 # Divide at instruction boundary, retaining full verbatim prompt.
 cut=next((i for i,x in enumerate(blocks) if x.startswith('Используй landing')),len(blocks)//2)
 for j,chunk in enumerate([blocks[:cut],blocks[cut:]],1):
  add(f'ШАГ 0{idx} / ПРОМПТ {j} ИЗ 2',label+f'<small>Часть {j} — '+('ваши данные' if j==1 else 'требования к сайту')+'</small>', '<div class="prompt">'+html.escape('\n\n'.join(chunk))+'</div>'+ (md(after) if j==2 else ''))
for idx in [6,7,8]:
 title,body=parts[idx].split('\n',1)
 if idx==6:
  chunks=body.split('### ')
  add('ШАГ 06 / ПРОВЕРКА',title,md(chunks[0]))
  for chunk in chunks[1:]:
   sub,txt=chunk.split('\n',1)
   add('ШАГ 06 / ДИЗАЙН И ПРАВКИ',sub,md(txt))
 else:
  add(f'ШАГ 0{idx}',title,md(body))

# Real editing examples from this project.
tail=pages[-2:];pages=pages[:-2]
cases=[('Фотографии не закрывают текст', 'Оставь только три приложенные фотографии. Сделай их крупнее и расположи вокруг заголовка так, чтобы они не перекрывали буквы. Проверь первый экран на компьютере и телефоне.', 'Назовите количество картинок и укажите, что именно должно оставаться читаемым.'), ('Заменяем конкретные фотографии', 'В блоке материалов замени левую фотографию на приложенное фото с блокнотом, а правую — на фото со стикерами. Заголовки, ссылки и расположение карточек сохрани.', 'Прикладывайте скриншот блока и новые файлы в одном сообщении. Объясните, какой файл куда поставить.'), ('Два логотипа вместо наложений', 'На первом экране оставь только логотипы ChatGPT и Kimi. Размести их у противоположных краёв, около середины экрана. Убери смену и наложение логотипов. Они не должны закрывать имя и кнопки.', 'Просите исправить конкретный элемент, а затем проверить его на узком экране.'), ('Центрирование и движение', 'Слово «ОПОРОЙ» выровняй по центру всей ширины экрана. При прокрутке оно должно плавно увеличиваться относительно своего центра, без смещения влево. Фотографии не должны перекрывать слово.', 'Уточняйте, относительно чего центрировать элемент. Для анимации укажите действие пользователя и ожидаемое движение.'), ('Новые фото и нужный масштаб', 'В блоке о школе замени фото слева на цветы, справа — на руки с красной нитью. Увеличь фотографии, оставив свободное место вокруг текста. На телефоне перенеси фотографии ниже текста.', 'Не ограничивайтесь «красиво»: назовите размер, место и поведение на телефоне.')]
for i,(title,prompt,lesson) in enumerate(cases,1):
 body='<p>Реальная правка из истории работы: промежуточные версии, а не текущий вид сайта. Пример показывает, как объяснить изменение без дизайнерских терминов.</p>'
 body+='<div class="case-pair"><div><h3>Было · скриншот</h3>'+img(f'case-{i}-before.png')+'</div><div><h3>Стало · результат</h3>'+img(f'case-{i}-after.png')+'</div></div>'
 body+='<h3>Запрос для копирования</h3><div class="prompt">'+html.escape(prompt)+'</div><div class="note">'+lesson+'</div><p class="case-tip">Это пример формулировки: замените названия, изображения и тексты своими.</p>'
 add(f'ПРАКТИКА / ПРАВКА {i:02}',title,body,'case-page')
add('ВИЗИТКА / СОБСТВЕННЫЙ ВИЗУАЛ','Имя слева.<br>3D-голова справа.',img('nikolskaya-1440.png')+md('Не обязательно искать готовую фотографию. Можно сгенерировать отдельное изображение и добавить его на сайт. На примере — мой готовый 3D-аватар. Вы можете создать свой: приложить фото и описать нужную стилизацию.\n\n1. В чате с генерацией изображений отправьте промпт со следующей страницы.\n2. Если нужен ваш образ, приложите своё фото и добавьте: «Сохрани мои узнаваемые черты лица, измени только материал и свет».\n3. Скачайте понравившийся результат кнопкой скачивания изображения и сохраните в папку проекта.\n4. Прикрепите файл к запросу на обновление сайта.\n5. Проверьте первый экран на компьютере и телефоне.')+'<div class="note">3D здесь — стиль картинки. Изображение само по себе не становится интерактивной 3D-моделью. Для лёгкого движения можно отдельно попросить плавный параллакс.</div>')
add('ВИЗИТКА / ГОТОВЫЕ ПРОМПТЫ','Создайте и добавьте<br>свой визуал.','<h3>1. Создать изображение</h3><div class="prompt">'+html.escape('Используй приложенное моё фото как референс внешности. Создай стилизованную парящую 3D-голову без тела, сохрани узнаваемые черты лица. Плавная округлая анатомия, слегка преувеличенные пропорции, спокойное выражение, глянцевые губы. Кожа с эффектом полированного фарфора: яркие блики, мягкое подповерхностное рассеивание, минимум микродеталей. Волосы — [ВАША ПРИЧЁСКА И ЦВЕТ], плавные объёмные пряди с блестящей поверхностью. Аксессуары — [ОЧКИ, НАУШНИКИ ИЛИ БЕЗ АКСЕССУАРОВ]. Качество рекламного CGI, мягкий кинематографичный свет, чистый игрушечный 3D-образ. Анфас. Голова и волосы целиком в кадре, с небольшими полями. Прозрачный фон, PNG. Без текста и водяных знаков.')+'</div><h3>2. Добавить на сайт</h3><div class="prompt">'+html.escape('Обнови первый экран моего сайта-визитки. Слева размести [ИМЯ] и [ФАМИЛИЯ] в две строки, ниже — [КОРОТКОЕ ОПИСАНИЕ] и кнопку [ДЕЙСТВИЕ]. Справа поставь приложенное изображение 3D-головы крупно. Не перекрывай изображением текст и кнопки. Сохрани пропорции головы. Фон сайта согласуй с фоном картинки, чтобы не было заметной прямоугольной рамки. На телефоне: сначала имя и фамилия, затем изображение, описание и кнопка. Остальные разделы сохрани. Проверь читаемость и отсутствие горизонтального скролла.')+'</div><div class="note">Промпт адаптирован по присланному референсу. Замените поля в скобках своими данными. Очки и наушники необязательны. Если фон получился непрозрачным, попросите: «Удали только фон, сохрани лицо, волосы и аксессуары». Прикладывайте именно файл изображения, а не скриншот чата.</div>')
add('ДВИЖЕНИЕ / ЧЕСТНО О 3D','Картинка или<br>настоящая модель?',md('**3D-аватар PNG** — обычная картинка, нарисованная в объёмном стиле. В нашей визитке используется именно она.\n\n**Реакция на курсор** — наклон всей картинки. Он делает экран живее, но не показывает затылок и новые ракурсы лица.\n\n**Видео** показывает заранее созданное движение. Можно связать кадр с курсором, но это не свободно вращаемая модель.\n\n**Модель GLB** содержит геометрию и материалы. Её можно вращать как объект в Blender. Для этого сначала нужен отдельный этап создания модели; одного PNG недостаточно.')+'<h3>Запрос для текущей картинки</h3><div class="prompt">Добавь моему PNG-аватару плавный наклон за курсором. Сделай эффект заметным, но без обрезки и наложения на текст. При уходе курсора возвращай в исходное положение. На телефоне и при уменьшении движения в настройках отключи эффект.</div>'+md('Для следующего шага: [Meshy Image to 3D](https://www.meshy.ai/features/image-to-3d/) создаёт модель из изображения. Результат нужно проверить: сходство, волосы, очки и профиль могут потребовать доработки.'))
add('ПОЛЕЗНЫЕ ССЫЛКИ','Всё в одном месте',md('### Сайты-примеры\n- [Визитка с 3D-аватаром](https://ekaterinaglowme.github.io/ai-sites-showcase/nikolskaya-romans/)\n- [Школа «Опора»](https://ekaterinaglowme.github.io/ai-sites-showcase/opora/)\n\nЭти две ссылки публичные: посетителю не нужен аккаунт GitHub. Ваш локальный сайт пока доступен только на вашем компьютере.\n\n### Навыки и установка\n- [landing-page-design](https://github.com/elayadesign/ai-design-skills/tree/main/skills/landing-page-design)\n- [Taste Skill](https://github.com/Leonxlnx/taste-skill/tree/main/skills/taste-skill)\n- [Hallmark](https://github.com/Nutlope/hallmark/tree/main/skills/hallmark)\n- [Встроенный skill-installer](https://github.com/openai/skills/tree/main/skills/.system/skill-installer)\n- [Навык imagegen](https://github.com/openai/skills/tree/main/skills/.system/imagegen)\n\nГенерация картинки и установка навыка — разные вещи. Если imagegen уже есть в Codex, скачивать его повторно не нужно. В обычном чате с генерацией изображений можно отправить тот же промпт без установки навыков.\n\n### Справка\n- [Начало работы с приложением](https://learn.chatgpt.com/docs/quickstart)\n- [Навыки в Codex](https://learn.chatgpt.com/docs/build-skills)\n- [Node.js](https://nodejs.org/en/download)\n- [Pinterest](https://www.pinterest.com/)\n- [GitHub](https://github.com/signup)')+'<div class="note">Интерфейсы и способы установки обновляются. Если пункт меню отличается, приложите скриншот и попросите Codex подсказать следующий шаг для вашей версии.</div>')
pages+=tail
css='''@page{size:A4;margin:0}*{box-sizing:border-box}body{margin:0;color:#141719;font-family:Arial,sans-serif;font-size:11pt;line-height:1.48} .page{padding:17mm 18mm 20mm;min-height:297mm;page-break-before:always;position:relative;background:#f7f5f0}.page:first-child{page-break-before:auto}.kicker{font-size:8pt;letter-spacing:1.1px;font-weight:700;border-bottom:1px solid #c8cdd3;padding-bottom:4mm;margin-bottom:9mm;display:flex;justify-content:space-between;color:#52606e}h1{font-size:31pt;line-height:1.06;letter-spacing:-1px;margin:0 0 9mm;font-weight:750}h1 small{display:block;font-size:15pt;letter-spacing:0;margin-top:4mm;color:#63738b}h3{font-size:14pt;line-height:1.2;margin:6mm 0 3mm}p{margin:0 0 4mm}a{color:#305ba1;text-decoration:underline;overflow-wrap:anywhere}li{margin-bottom:3mm}ol,ul{padding-left:6mm}code{font-size:9.4pt;overflow-wrap:anywhere}pre,.prompt{font-family:Arial,sans-serif;white-space:pre-wrap;overflow-wrap:anywhere;background:#e8eef9;border-left:3px solid #7199ed;padding:5mm;font-size:10pt;line-height:1.42;margin:4mm 0}pre code{font-family:Arial,sans-serif;font-size:10pt}.prompt{font-size:10.5pt;line-height:1.45}table{border-collapse:collapse;width:100%;font-size:9.7pt;margin:5mm 0}th{text-align:left;background:#cdddf9}td,th{padding:3mm;border-bottom:1px solid #c5ccd6;vertical-align:top}tr{break-inside:avoid}td code{font-family:Arial,sans-serif}.shot{width:100%;display:block;border-radius:4mm;border:1px solid #d1d6df;margin-bottom:4mm}.example .shot{height:66mm;object-fit:contain;object-position:center;background:#090909}.example p{font-size:10pt}.example h3{margin:2mm 0}.example{margin-bottom:6mm}.note{background:#dce6f9;border-radius:3mm;padding:5mm;font-size:10.5pt;margin-top:6mm}.cover{background:#111314;color:#f7f5f0}.cover .kicker{color:#97b7ff;border-color:#3f4856}.cover h1{font-size:58pt;letter-spacing:-2px;margin-top:14mm}.lead{font-size:18pt;color:#b4c9ee;margin:7mm 0 10mm}.cover .shot{border-color:#41454b}.pill{display:inline-block;background:#93b1f7;color:#111;padding:2mm 4mm;border-radius:8mm;font-size:8pt;font-weight:bold;margin:3mm 2mm 0 0}.cover-bottom{font-size:12pt;margin-top:10mm;color:#d1d5dd}.steps>div{position:relative;padding:0 0 6mm 17mm;border-bottom:1px solid #cdd3dc;margin-bottom:6mm}.steps b{position:absolute;left:0;font-size:24pt;color:#7699d8}.steps h3{margin-top:0}h1,h3{break-after:avoid}p{orphans:3;widows:3}'''
css += """html,body{background:#101212;color:#f4f4ef;-webkit-print-color-adjust:exact;print-color-adjust:exact}.page,.cover{background:#101212;color:#f4f4ef;width:210mm;min-height:297mm}.kicker,.cover .kicker{color:#a7bff2;border-color:#3c4249}h1 small{color:#b0bfda}a{color:#a7c5ff}pre,.prompt{background:#1d242c;color:#f4f4ef;border-left-color:#91b4fb}.note{background:#1d242c;color:#f4f4ef}th{background:#293341;color:#eaf1ff}td,th,.steps>div{border-color:#3a424a}.shot{border-color:#40474d}.steps b{color:#a7bff2}.page-number{position:absolute;bottom:9mm;right:18mm;color:#9aa5b6;font-size:8pt}"""
css += ".case-pair{display:grid;grid-template-columns:1fr 1fr;gap:5mm;margin:7mm 0}.case-pair h3{font-size:10pt;margin:0 0 3mm;color:#a7bff2}.case-pair .shot{height:83mm;object-fit:contain;background:#181b1e;border-radius:2mm}.case-page h1{font-size:30pt}.case-page .prompt{font-size:12pt}.case-tip{font-size:9pt;color:#b0bfda;margin-top:5mm}"
