css += ".page:nth-child(25) .shot{max-height:82mm;object-fit:contain}.page:nth-child(25){font-size:10pt}.page:nth-child(25) li{margin-bottom:2mm}.page:nth-child(25) h1{margin-bottom:6mm}.page:nth-child(25) .note{font-size:9.5pt}"
css += ".cover h1{font-size:50pt;margin-top:8mm}.cover .lead{font-size:16pt;margin:6mm 0 7mm}.cover .shot{height:91mm;object-fit:contain;background:#090909}.cover-bottom{margin-top:6mm}.cover .kicker{font-size:7pt}"
