htmlpath.write_text('<!doctype html><html lang="ru"><meta charset="utf-8"><title>Ваш первый сайт с ИИ — @nikolskaya.ai</title><style>'+css+'</style>'+''.join(pages)+'</html>')
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless=True)
